package com.ledgerbase.backend.model;

import java.math.BigDecimal;
import java.time.OffsetDateTime;

/**
 * Represents one debit or credit entry within a financial transaction.
 *
 * Maps to the PostgreSQL "ledger_entries" table.
 *
 * A financial transaction normally contains at least two entries,
 * and its total debits must equal its total credits before posting.
 */
public class LedgerEntry {

    // Unique entry ID generated by PostgreSQL.
    private Long id;

    // Business that owns this ledger entry.
    private Long businessId;

    // Parent financial transaction.
    private Long transactionId;

    // Account affected by this entry.
    private Long accountId;

    // Amount debited to this account.
    // BigDecimal avoids floating-point precision problems.
    private BigDecimal debit;

    // Amount credited to this account.
    private BigDecimal credit;

    // Timestamp when the entry was created.
    private OffsetDateTime createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getBusinessId() {
        return businessId;
    }

    public void setBusinessId(Long businessId) {
        this.businessId = businessId;
    }

    public Long getTransactionId() {
        return transactionId;
    }

    public void setTransactionId(Long transactionId) {
        this.transactionId = transactionId;
    }

    public Long getAccountId() {
        return accountId;
    }

    public void setAccountId(Long accountId) {
        this.accountId = accountId;
    }

    public BigDecimal getDebit() {
        return debit;
    }

    public void setDebit(BigDecimal debit) {
        this.debit = debit;
    }

    public BigDecimal getCredit() {
        return credit;
    }

    public void setCredit(BigDecimal credit) {
        this.credit = credit;
    }

    public OffsetDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(OffsetDateTime createdAt) {
        this.createdAt = createdAt;
    }
}
